import React from 'react';
import MotionResults from './components/MotionResults';
import VotingResults from './components/VotingResults';
import SpeakerStartVote from './components/SpeakerStartVote';
import VotingPage from './components/VotingPage';

const App = () => {
  // Sample data for component props
  const sampleMotionName = "Sample Motion";
  const sampleUserVote = "For";
  const sampleForVotes = 10;
  const sampleAgainstVotes = 5;
  const sampleAbstainVotes = 2;
  const sampleThreshold = 2 / 3;
  const sampleOnClose = () => alert("Close button clicked");
  const sampleVotes = [
    { name: "User1", vote: "For" },
    { name: "User2", vote: "Against" },
    { name: "User3", vote: "Abstain" },
  ];
  const sampleOnStart = (data) => console.log("Vote started with data:", data);
  const sampleOnVoteSubmit = (vote) => console.log("Vote submitted:", vote);

  return (
    <BrowserRouter>
      <div>
        {/* Navigation Menu */}
        <nav style={{ padding: '10px', backgroundColor: '#f0f0f0', borderBottom: '1px solid #ccc' }}>
          <ul style={{ listStyle: 'none', display: 'flex', gap: '20px', margin: 0, padding: '0 20px' }}>
            <li><Link to="/motion-results">Motion Results</Link></li>
            <li><Link to="/voting-results">Voting Results</Link></li>
            <li><Link to="/speaker-start-vote">Speaker Start Vote</Link></li>
            <li><Link to="/voting-page">Voting Page</Link></li>
          </ul>
        </nav>

        {/* Route Definitions */}
        <Routes>
          <Route path="/motion-results" element={
            <MotionResults
              motionName={sampleMotionName}
              userVote={sampleUserVote}
              forVotes={sampleForVotes}
              againstVotes={sampleAgainstVotes}
              abstainVotes={sampleAbstainVotes}
              threshold={sampleThreshold}
              onClose={sampleOnClose}
            />
          } />
          <Route path="/voting-results" element={
            <VotingResults
              motionTitle={sampleMotionName}
              status="passed"
              votes={sampleVotes}
            />
          } />
          <Route path="/speaker-start-vote" element={
            <SpeakerStartVote
              onStart={sampleOnStart}
              onClose={sampleOnClose}
            />
          } />
          <Route path="/voting-page" element={
            <VotingPage
              voteType="Motion"
              motionName={sampleMotionName}
              motionID="123"
              userID="user1"
              voteCounts={{ for: 0, against: 0, abstain: 0 }}
              onVoteSubmit={sampleOnVoteSubmit}
            />
          } />
          {/* Optional: Default route */}
          <Route path="/" element={<h2 style={{ textAlign: 'center', marginTop: '20px' }}>Select a component from the menu above</h2>} />
        </Routes>
      </div>
    </BrowserRouter>
  );
};

export default App;
